CREATE TABLE subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT, endpoint TEXT NOT NULL UNIQUE, owner TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, country TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', tested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE jobs(id TEXT PRIMARY KEY, payload TEXT NOT NULL, ceiling INTEGER NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE deliveries(job TEXT NOT NULL, recipient INTEGER NOT NULL, status INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL DEFAULT (unixepoch()), PRIMARY KEY(job,recipient));
CREATE INDEX delivery_counts ON deliveries(job,status);
